// CRM extension: shared operational cases, explicitly reconciled identities and confirmed events.
// This module does not create tables, grant logins, dispatch messages or guess identities.
const crmUUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
const crmStages=['recebido','em_acolhimento','em_analise','encaminhado','agendado','concluido','lista_espera','arquivado'];
const crmPriorities=['baixa','normal','alta','urgente'];
class CrmInputError extends Error{constructor(message,status=400){super(message);this.status=status;}}
function crmAssert(condition,message,status=400){if(!condition)throw new CrmInputError(message,status);}
function crmText(value,max,label,min=0){if(value===undefined||value===null)value='';crmAssert(typeof value==='string'&&value.length<=max&&value.trim().length>=min,'Confira '+label+'.');return value.trim();}
function crmID(value,label,required=false){const id=value===undefined||value===null||value===''?null:value;crmAssert(!required||id,'Informe '+label+'.');crmAssert(id===null||(typeof id==='string'&&crmUUID.test(id)),'Confira '+label+'.');return id;}
function crmBool(value,label,defaultValue=true){if(value===undefined)value=defaultValue;crmAssert(typeof value==='boolean','Confira '+label+'.');return value?1:0;}
function crmEnum(value,allowed,label){crmAssert(allowed.includes(value),'Confira '+label+'.');return value;}
function crmToday(){return new Date(Date.now()-3*3600000).toISOString().slice(0,10);}
function crmPeriod(value){const period=value||crmToday().slice(0,7);crmAssert(typeof period==='string'&&/^20\d{2}-(0[1-9]|1[0-2])$/.test(period),'Período inválido.');return period;}
function crmDate(value,label,required=false){if(value===undefined||value===null||value===''){crmAssert(!required,'Informe '+label+'.');return null;}crmAssert(typeof value==='string'&&/^20\d{2}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value,'Confira '+label+'.');return value;}
function crmEmail(value){const email=crmText(value,150,'o e-mail').toLowerCase();crmAssert(!email||/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email),'Informe um e-mail válido.');return email;}
function crmPhone(value){const raw=crmText(value,30,'o telefone');const phone=raw.replace(/[\s()+.-]/g,'');crmAssert(!raw||/^\d{10,15}$/.test(phone),'Informe telefone com DDD, usando de 10 a 15 números.');return phone;}
function crmContacts(value=[]){crmAssert(Array.isArray(value)&&value.length<=10,'Confira os contatos da pessoa.');const seen=new Set();return value.map(contact=>{crmAssert(contact&&typeof contact==='object','Confira os contatos.');const tipo=crmEnum(contact.tipo,['email','telefone'],'o tipo de contato'),valor=tipo==='email'?crmEmail(contact.valor):crmPhone(contact.valor);crmAssert(valor,'Preencha o contato ou remova a linha vazia.');const key=tipo+'|'+valor;crmAssert(!seen.has(key),'Há contatos repetidos.');seen.add(key);return{tipo,valor};});}
function crmIDs(value,label){crmAssert(Array.isArray(value)&&value.length<=100,'Confira '+label+'.');const ids=value.map(id=>crmID(id,label,true));crmAssert(new Set(ids).size===ids.length,'Há vínculos repetidos em '+label+'.');return ids;}
async function crmBody(req){const raw=await req.text();crmAssert(raw.length<=30000,'Dados muito longos.',413);let body;try{body=JSON.parse(raw);}catch{throw new CrmInputError('Envie dados válidos.');}crmAssert(body&&typeof body==='object'&&!Array.isArray(body),'Envie um registro válido.');return body;}
async function crmAll(env,sql,args=[]){return(await env.DB.prepare(sql).bind(...args).all()).results;}
async function crmRow(env,table,id,label,required=false){if(!id){crmAssert(!required,'Informe '+label+'.');return null;}const row=await env.DB.prepare('SELECT * FROM '+table+' WHERE id=?').bind(id).first();crmAssert(row&&(table!=='op_profissionais'||!row.somente_agenda),label+' não encontrado.',404);return row;}
function crmUpsert(env,table,id,values,now){const columns=['id',...Object.keys(values),'criado_em','atualizado_em'];return env.DB.prepare('INSERT INTO '+table+'('+columns.join(',')+') VALUES('+columns.map(()=>'?').join(',')+') ON CONFLICT(id) DO UPDATE SET '+[...Object.keys(values),'atualizado_em'].map(k=>k+'=excluded.'+k).join(',')).bind(id,...Object.values(values),now,now);}
function crmAudit(env,req,action,id,now){return env.DB.prepare('INSERT INTO auditoria(id,ator,acao,registro_id,criado_em) VALUES(?,?,?,?,?)').bind(crypto.randomUUID(),req.headers.get('oai-authenticated-user-id'),action,id,now);}
function crmMovement(env,req,caseID,type,text,now){return env.DB.prepare('INSERT INTO crm_movimentos(id,apoio_id,tipo,texto,ator,criado_em) VALUES(?,?,?,?,?,?)').bind(crypto.randomUUID(),caseID,type,text,req.headers.get('oai-authenticated-user-id'),now);}
async function crmWrite(env,req,id,statements,action,caseID,text,now=new Date().toISOString()){await env.DB.batch([...statements,crmAudit(env,req,action,id,now),...(caseID?[crmMovement(env,req,caseID,action,text,now)]:[])]);return json({ok:true,id,atualizado_em:now});}
const crmEvents=`WITH eventos AS (
 SELECT 'agenda:'||a.id AS evento_id,a.cadastro_id,a.familia_id,date(a.data_hora,'-3 hours') AS data_ocorrencia,1 AS quantidade,'atendimento' AS tipo,'atendimento' AS unidade_medida FROM op_agenda a WHERE a.situacao='realizado' AND NOT EXISTS(SELECT 1 FROM crm_realizacoes r WHERE r.agenda_id=a.id)
 UNION ALL
 SELECT 'crm:'||r.id,a.cadastro_id,r.familia_id,r.data_ocorrencia,r.quantidade,s.tipo,s.unidade_medida FROM crm_realizacoes r JOIN op_apoios a ON a.id=r.apoio_id JOIN crm_servicos s ON s.id=r.servico_id WHERE r.status='realizado' AND (r.agenda_id IS NULL OR EXISTS(SELECT 1 FROM op_agenda ag WHERE ag.id=r.agenda_id AND ag.situacao='realizado'))
)`;
async function crmImpactMetrics(env,period){period=crmPeriod(period);const totals=await env.DB.prepare(crmEvents+` SELECT count(DISTINCT m.pessoa_id) AS pessoas_apoiadas,count(DISTINCT e.familia_id) AS familias_apoiadas,count(*) AS atividades_realizadas,COALESCE(sum(CASE WHEN e.tipo='cesta' THEN e.quantidade ELSE 0 END),0) AS cestas_entregues,COALESCE(sum(CASE WHEN e.unidade_medida='peca' THEN e.quantidade ELSE 0 END),0) AS pecas_entregues,COALESCE(sum(CASE WHEN e.unidade_medida='item' THEN e.quantidade ELSE 0 END),0) AS itens_entregues,count(DISTINCT CASE WHEN m.pessoa_id IS NULL THEN e.cadastro_id END) AS cadastros_sem_identidade FROM eventos e LEFT JOIN crm_cadastro_pessoas m ON m.cadastro_id=e.cadastro_id WHERE substr(e.data_ocorrencia,1,7)=?`).bind(period).first();return{periodo:period,...totals,criterio:'Somente entregas e atividades realizadas. Pessoas com identidade conciliada são contadas uma vez no mês; famílias são vínculos explícitos, sem multiplicar membros. Cadastros ainda não conciliados ficam separados. Quantidade de cestas não é quantidade de pessoas. Encaminhamentos, inscrições e totais históricos manuais não são somados.'};}
async function crmConfirmedMonths(env){return(await crmAll(env,crmEvents+" SELECT substr(data_ocorrencia,1,7) AS periodo FROM eventos WHERE data_ocorrencia IS NOT NULL GROUP BY periodo ORDER BY periodo DESC LIMIT 120")).map(row=>row.periodo);}
async function handleCrmPublic(req,env,path){if(path!=='/api/crm/impacto'||req.method!=='GET')return;try{return json(await crmImpactMetrics(env,new URL(req.url).searchParams.get('periodo')));}catch(error){if(error instanceof CrmInputError)return json({error:error.message},error.status);throw error;}}
function crmPagination(url,limit=30){const raw=url.searchParams.get('pagina')||'1';crmAssert(/^\d{1,7}$/.test(raw)&&Number(raw)>=1,'Página inválida.');const pagina=Number(raw);return{pagina,limite:limit,offset:(pagina-1)*limit};}
function crmLike(value){return '%'+value.replace(/[\\%_]/g,'\\$&')+'%';}
async function crmEntityList(env,entity,url,base=false){
 const config={pessoas:{table:'crm_pessoas',where:"(nome LIKE ? ESCAPE '\\' OR EXISTS(SELECT 1 FROM crm_pessoa_contatos ct WHERE ct.pessoa_id=crm_pessoas.id AND ct.valor LIKE ? ESCAPE '\\'))",count:2},familias:{table:'op_familias',where:"(nome_referencia LIKE ? ESCAPE '\\' OR contato LIKE ? ESCAPE '\\')",count:2},profissionais:{table:'op_profissionais',where:"(nome LIKE ? ESCAPE '\\' OR funcao LIKE ? ESCAPE '\\' OR email LIKE ? ESCAPE '\\')",count:3},servicos:{table:'crm_servicos',where:"(nome LIKE ? ESCAPE '\\')",count:1},unidades:{table:'crm_unidades',where:"(nome LIKE ? ESCAPE '\\' OR email LIKE ? ESCAPE '\\' OR telefone LIKE ? ESCAPE '\\')",count:3}}[entity];
 crmAssert(config,'Área de consulta inválida.');const query=crmText(url.searchParams.get(base?entity+'_busca':'busca')||(base&&entity==='pessoas'?url.searchParams.get('busca'):'')||'',120,'a busca');const filters=[];if(entity==='profissionais')filters.push('somente_agenda=0');if(query)filters.push(config.where);const where=filters.length?' WHERE '+filters.join(' AND '):'',args=query?Array(config.count).fill(crmLike(query)):[];const page=base?{pagina:1,limite:500,offset:0}:crmPagination(url,50);const total=(await env.DB.prepare('SELECT count(*) AS total FROM '+config.table+where).bind(...args).first()).total;const sub='SELECT id FROM '+config.table+where+' ORDER BY atualizado_em DESC,id LIMIT ? OFFSET ?',subargs=[...args,page.limite,page.offset];let items=await crmAll(env,'SELECT * FROM '+config.table+where+' ORDER BY atualizado_em DESC,id LIMIT ? OFFSET ?',subargs);
 if(entity==='pessoas'){const mappings=await crmAll(env,'SELECT cadastro_id,pessoa_id FROM crm_cadastro_pessoas WHERE pessoa_id IN ('+sub+')',subargs),contacts=await crmAll(env,'SELECT * FROM crm_pessoa_contatos WHERE pessoa_id IN ('+sub+')',subargs),families=await crmAll(env,'SELECT * FROM crm_familia_membros WHERE pessoa_id IN ('+sub+')',subargs);items=items.map(row=>({...row,cadastros_ids:mappings.filter(m=>m.pessoa_id===row.id).map(m=>m.cadastro_id),contatos:contacts.filter(c=>c.pessoa_id===row.id).map(({tipo,valor})=>({tipo,valor})),familias:families.filter(f=>f.pessoa_id===row.id).map(({familia_id,papel})=>({familia_id,papel}))}));}
 if(entity==='familias'){const members=await crmAll(env,'SELECT m.*,p.nome FROM crm_familia_membros m JOIN crm_pessoas p ON p.id=m.pessoa_id WHERE m.familia_id IN ('+sub+')',subargs);items=items.map(row=>({...row,membros:members.filter(m=>m.familia_id===row.id).map(({pessoa_id,papel,nome})=>({pessoa_id,papel,nome}))}));}
 if(entity==='unidades'){const links=await crmAll(env,'SELECT * FROM crm_unidade_servicos WHERE unidade_id IN ('+sub+')',subargs);items=items.map(row=>({...row,servicos_ids:links.filter(l=>l.unidade_id===row.id).map(l=>l.servico_id)}));}
 if(entity==='profissionais'){const links=await crmAll(env,'SELECT * FROM crm_profissional_servicos WHERE profissional_id IN ('+sub+')',subargs),slots=await crmAll(env,'SELECT * FROM crm_disponibilidades WHERE profissional_id IN ('+sub+') ORDER BY dia_semana,inicio_minuto',subargs);items=items.map(row=>({...row,servicos_ids:links.filter(l=>l.profissional_id===row.id).map(l=>l.servico_id),disponibilidades:slots.filter(s=>s.profissional_id===row.id)}));}
 return{items,total,pagina:page.pagina,limite:page.limite,parcial:total>items.length+page.offset};
}
const crmCaseSelect=`SELECT a.*,c.nome AS cadastro_nome,m.pessoa_id,p.nome AS pessoa_nome,d.servico_id,s.nome AS servico_nome,s.tipo AS servico_tipo,d.prioridade,d.prazo,d.versao AS crm_versao,e.nome AS profissional_nome,e.somente_agenda AS responsavel_coletivo,f.nome_referencia AS familia_nome,(SELECT count(*) FROM crm_tarefas t WHERE t.apoio_id=a.id AND t.situacao='aberta') AS tarefas_abertas,CASE WHEN d.prazo IS NOT NULL AND d.prazo<date('now','-3 hours') AND a.etapa NOT IN ('concluido','arquivado') THEN 1 ELSE 0 END AS atrasado,CASE WHEN m.pessoa_id IS NULL THEN 1 ELSE 0 END AS pendente_identidade FROM op_apoios a JOIN cadastros c ON c.id=a.cadastro_id LEFT JOIN crm_cadastro_pessoas m ON m.cadastro_id=a.cadastro_id LEFT JOIN crm_pessoas p ON p.id=m.pessoa_id LEFT JOIN crm_apoio_detalhes d ON d.apoio_id=a.id LEFT JOIN crm_servicos s ON s.id=d.servico_id LEFT JOIN op_profissionais e ON e.id=a.profissional_id LEFT JOIN op_familias f ON f.id=a.familia_id`;
async function crmCaseList(env,url){const filters=[],args=[];for(const[key,column]of [['etapa','a.etapa'],['servico_id','d.servico_id'],['prioridade','d.prioridade'],['profissional_id','a.profissional_id']]){const val=url.searchParams.get(key);if(val){if(key==='etapa')crmEnum(val,crmStages,'a etapa');else if(key==='prioridade')crmEnum(val,crmPriorities,'a prioridade');else crmID(val,key,true);filters.push(column+'=?');args.push(val);}}const busca=crmText(url.searchParams.get('busca')||'',120,'a busca');if(busca){filters.push("(c.nome LIKE ? ESCAPE '\\' OR p.nome LIKE ? ESCAPE '\\' OR s.nome LIKE ? ESCAPE '\\' OR a.proxima_acao LIKE ? ESCAPE '\\')");args.push(...Array(4).fill(crmLike(busca)));}const where=filters.length?' WHERE '+filters.join(' AND '):'',page=crmPagination(url),query=crmCaseSelect+where;const total=(await env.DB.prepare('SELECT count(*) AS total FROM ('+query+')').bind(...args).first()).total;return{items:await crmAll(env,query+" ORDER BY CASE d.prioridade WHEN 'urgente' THEN 0 WHEN 'alta' THEN 1 WHEN 'normal' THEN 2 ELSE 3 END,a.atualizado_em DESC,a.id LIMIT ? OFFSET ?",[...args,page.limite,page.offset]),total,pagina:page.pagina,limite:page.limite};}
async function crmCaseDetail(env,id){const item=await env.DB.prepare(crmCaseSelect+' WHERE a.id=?').bind(id).first();crmAssert(item,'Apoio não encontrado.',404);const cadastro=await crmRow(env,'cadastros',item.cadastro_id,'Cadastro'),pessoa=item.pessoa_id?await crmRow(env,'crm_pessoas',item.pessoa_id,'Pessoa'):null;if(pessoa)pessoa.contatos=await crmAll(env,'SELECT tipo,valor FROM crm_pessoa_contatos WHERE pessoa_id=?',[pessoa.id]);const encaminhamentos=await crmAll(env,'SELECT r.*,u.nome AS unidade_nome,p.nome AS profissional_nome FROM crm_encaminhamentos r JOIN crm_unidades u ON u.id=r.unidade_id LEFT JOIN op_profissionais p ON p.id=r.profissional_id WHERE r.apoio_id=? ORDER BY r.criado_em DESC LIMIT 100',[id]);const realizacoes=await crmAll(env,'SELECT r.*,s.nome AS servico_nome,s.tipo AS servico_tipo,s.unidade_medida,p.nome AS profissional_nome,u.nome AS unidade_nome FROM crm_realizacoes r JOIN crm_servicos s ON s.id=r.servico_id LEFT JOIN op_profissionais p ON p.id=r.profissional_id LEFT JOIN crm_unidades u ON u.id=r.unidade_id WHERE r.apoio_id=? ORDER BY r.data_ocorrencia DESC,r.criado_em DESC LIMIT 100',[id]);const tarefas=await crmAll(env,'SELECT t.*,p.nome AS responsavel_nome FROM crm_tarefas t LEFT JOIN op_profissionais p ON p.id=t.responsavel_id WHERE t.apoio_id=? ORDER BY t.prazo,t.criado_em LIMIT 100',[id]);const historico=await crmAll(env,'SELECT id,tipo,texto,criado_em FROM crm_movimentos WHERE apoio_id=? ORDER BY criado_em DESC,id DESC LIMIT 100',[id]);const agenda=await crmAll(env,'SELECT id,tipo,data_hora,situacao,profissional_id FROM op_agenda WHERE apoio_id=? OR (apoio_id IS NULL AND cadastro_id=?) ORDER BY data_hora DESC LIMIT 100',[id,item.cadastro_id]);let profissionais=[],unidades=[];if(item.servico_id){profissionais=await crmAll(env,"SELECT p.*,(SELECT count(*) FROM op_apoios a WHERE a.profissional_id=p.id AND a.etapa NOT IN ('concluido','arquivado')) AS carga_aberta FROM op_profissionais p JOIN crm_profissional_servicos ps ON ps.profissional_id=p.id WHERE ps.servico_id=? AND p.ativo=1 ORDER BY carga_aberta,p.nome LIMIT 100",[item.servico_id]);const slots=await crmAll(env,'SELECT d.* FROM crm_disponibilidades d JOIN crm_profissional_servicos ps ON ps.profissional_id=d.profissional_id JOIN op_profissionais p ON p.id=d.profissional_id WHERE ps.servico_id=? AND d.ativo=1 AND p.ativo=1 ORDER BY d.dia_semana,d.inicio_minuto',[item.servico_id]);profissionais=profissionais.map(p=>({...p,disponibilidades:slots.filter(s=>s.profissional_id===p.id)}));unidades=await crmAll(env,'SELECT u.* FROM crm_unidades u JOIN crm_unidade_servicos us ON us.unidade_id=u.id WHERE us.servico_id=? AND u.ativo=1 ORDER BY u.nome LIMIT 100',[item.servico_id]);}return{item,pessoa,cadastro,encaminhamentos,realizacoes,tarefas,historico,agenda,sugestoes:{profissionais,unidades,criterio:'Áreas e disponibilidade declaradas. A equipe precisa confirmar vagas e horários.'},limites:{historico:100,encaminhamentos:100,realizacoes:100,tarefas:100,agenda:100,sugestoes:100}};}
async function crmGlobalList(env,kind,url){const page=crmPagination(url),filters=[],args=[];const state=url.searchParams.get(kind==='realizacoes'?'status':'situacao');if(state){crmEnum(state,kind==='realizacoes'?['realizado','cancelado']:['aberta','concluida','cancelada'],'a situação');filters.push('r.'+(kind==='realizacoes'?'status':'situacao')+'=?');args.push(state);}const busca=crmText(url.searchParams.get('busca')||'',120,'a busca');if(busca){filters.push("(c.nome LIKE ? ESCAPE '\\' OR p.nome LIKE ? ESCAPE '\\' OR "+(kind==='realizacoes'?"s.nome":"r.titulo")+" LIKE ? ESCAPE '\\')");args.push(...Array(3).fill(crmLike(busca)));}const query=kind==='realizacoes'?`SELECT r.*,c.nome AS cadastro_nome,p.nome AS pessoa_nome,s.nome AS servico_nome,s.tipo AS servico_tipo,s.unidade_medida,e.nome AS profissional_nome FROM crm_realizacoes r JOIN op_apoios a ON a.id=r.apoio_id JOIN cadastros c ON c.id=a.cadastro_id LEFT JOIN crm_cadastro_pessoas m ON m.cadastro_id=c.id LEFT JOIN crm_pessoas p ON p.id=m.pessoa_id JOIN crm_servicos s ON s.id=r.servico_id LEFT JOIN op_profissionais e ON e.id=r.profissional_id`:`SELECT r.*,c.nome AS cadastro_nome,p.nome AS pessoa_nome,e.nome AS responsavel_nome FROM crm_tarefas r JOIN op_apoios a ON a.id=r.apoio_id JOIN cadastros c ON c.id=a.cadastro_id LEFT JOIN crm_cadastro_pessoas m ON m.cadastro_id=c.id LEFT JOIN crm_pessoas p ON p.id=m.pessoa_id LEFT JOIN op_profissionais e ON e.id=r.responsavel_id`;const where=filters.length?' WHERE '+filters.join(' AND '):'',total=(await env.DB.prepare('SELECT count(*) AS total FROM ('+query+where+')').bind(...args).first()).total;return{items:await crmAll(env,query+where+' ORDER BY '+(kind==='realizacoes'?'r.data_ocorrencia DESC,r.criado_em DESC':'r.prazo,r.criado_em')+' LIMIT ? OFFSET ?',[...args,page.limite,page.offset]),total,pagina:page.pagina,limite:page.limite};}
async function crmBase(env,url){await crmEnsureSupportCatalog(env);const results=await Promise.all(['pessoas','familias','profissionais','unidades'].map(entity=>crmEntityList(env,entity,url,true)));const base=Object.fromEntries(['pessoas','familias','profissionais','unidades'].map((k,i)=>[k,results[i].items])),servicos=await crmAll(env,'SELECT * FROM crm_servicos ORDER BY ativo DESC,nome LIMIT 200'),serviceTotal=(await env.DB.prepare('SELECT count(*) AS total FROM crm_servicos').first()).total;const page=crmPagination(url,50),args=[],filters=["c.tipo IN ('pessoa','acolhimento','contato')","c.situacao<>'arquivado'"];const busca=crmText(url.searchParams.get('busca')||'',120,'a busca');if(busca){filters.push("(c.nome LIKE ? ESCAPE '\\' OR c.contato LIKE ? ESCAPE '\\')");args.push(...Array(2).fill(crmLike(busca)));}if(url.searchParams.get('pendentes')==='1')filters.push('NOT EXISTS(SELECT 1 FROM op_apoios a WHERE a.cadastro_id=c.id)');const where=' WHERE '+filters.join(' AND '),total=(await env.DB.prepare('SELECT count(*) AS total FROM cadastros c'+where).bind(...args).first()).total;const cadastros=await crmAll(env,`SELECT c.id,c.tipo,c.nome,c.contato,c.mensagem,c.criado_em,m.pessoa_id,p.nome AS pessoa_nome,(SELECT count(*) FROM op_apoios a WHERE a.cadastro_id=c.id) AS casos_total,(SELECT a.id FROM op_apoios a WHERE a.cadastro_id=c.id ORDER BY a.atualizado_em DESC LIMIT 1) AS apoio_id FROM cadastros c LEFT JOIN crm_cadastro_pessoas m ON m.cadastro_id=c.id LEFT JOIN crm_pessoas p ON p.id=m.pessoa_id`+where+' ORDER BY casos_total,c.criado_em DESC,c.id LIMIT ? OFFSET ?',[...args,page.limite,page.offset]);return{...base,areas_responsaveis:opsResponsibleAreas,servicos,cadastros,cadastros_total:total,pagina:page.pagina,limite:page.limite,totais:{...Object.fromEntries(['pessoas','familias','profissionais','unidades'].map((k,i)=>[k,results[i].total])),servicos:serviceTotal},limites:{pessoas:500,familias:500,profissionais:500,unidades:500,servicos:200},parcial:results.some(r=>r.parcial)||serviceTotal>servicos.length};}
async function crmSummary(env,period){period=crmPeriod(period);const totals=await env.DB.prepare("SELECT count(*) AS abertos,COALESCE(sum(CASE WHEN profissional_id IS NULL THEN 1 ELSE 0 END),0) AS sem_responsavel FROM op_apoios WHERE etapa NOT IN ('concluido','arquivado')").first();const atrasados=(await env.DB.prepare("SELECT count(*) AS total FROM crm_apoio_detalhes d JOIN op_apoios a ON a.id=d.apoio_id WHERE d.prazo<date('now','-3 hours') AND a.etapa NOT IN ('concluido','arquivado')").first()).total;const tasks=await env.DB.prepare("SELECT count(*) AS tarefas_abertas,COALESCE(sum(CASE WHEN prazo<date('now','-3 hours') THEN 1 ELSE 0 END),0) AS tarefas_atrasadas FROM crm_tarefas WHERE situacao='aberta'").first();const triage=(await env.DB.prepare("SELECT count(*) AS total FROM cadastros c WHERE c.tipo IN ('pessoa','acolhimento','contato') AND c.situacao<>'arquivado' AND NOT EXISTS(SELECT 1 FROM op_apoios a WHERE a.cadastro_id=c.id)").first()).total;return{periodo:period,...totals,atrasados,aguardando_triagem:triage,...tasks,por_etapa:await crmAll(env,'SELECT etapa,count(*) AS total FROM op_apoios GROUP BY etapa'),por_servico:await crmAll(env,"SELECT s.id AS servico_id,s.nome,count(d.apoio_id) AS total FROM crm_servicos s LEFT JOIN crm_apoio_detalhes d ON d.servico_id=s.id LEFT JOIN op_apoios a ON a.id=d.apoio_id WHERE a.id IS NULL OR a.etapa NOT IN ('concluido','arquivado') GROUP BY s.id,s.nome ORDER BY s.nome"),impacto:await crmImpactMetrics(env,period),limites:{indicadores:'Consultas completas no banco; sem truncamento por página.'}};}
async function crmService(env,id,existingID=null){const row=await crmRow(env,'crm_servicos',crmID(id,'o tipo de apoio',true),'Tipo de apoio',true);crmAssert(row.ativo===1||row.id===existingID,'O tipo de apoio está inativo.');return row;}
async function crmCapableProfessional(env,id,serviceID,oldID=null){id=crmID(id,'o profissional');if(!id)return null;const row=await crmRow(env,'op_profissionais',id,'Profissional',true);if(id!==oldID){crmAssert(row.ativo===1,'O profissional está inativo.');crmAssert(await env.DB.prepare('SELECT 1 AS ok FROM crm_profissional_servicos WHERE profissional_id=? AND servico_id=?').bind(id,serviceID).first(),'O profissional não possui essa área de apoio cadastrada.');}return id;}
async function crmCapableUnit(env,id,serviceID,oldID=null){id=crmID(id,'o destino');if(!id)return null;const row=await crmRow(env,'crm_unidades',id,'Destino',true);if(id!==oldID){crmAssert(row.ativo===1,'O destino está inativo.');crmAssert(await env.DB.prepare('SELECT 1 AS ok FROM crm_unidade_servicos WHERE unidade_id=? AND servico_id=?').bind(id,serviceID).first(),'O destino não está configurado para receber este tipo de apoio.');}return id;}
async function crmCaseCore(env,id){return crmRow(env,'op_apoios',crmID(id,'o apoio',true),'Apoio',true);}
async function crmCaseService(env,caseID){const row=await env.DB.prepare('SELECT d.*,s.tipo FROM crm_apoio_detalhes d JOIN crm_servicos s ON s.id=d.servico_id WHERE d.apoio_id=?').bind(caseID).first();crmAssert(row,'Classifique o tipo de apoio na ficha antes de encaminhar ou registrar a realização.');return row;}
function crmNewSource(env,id,name,contacts,now){return env.DB.prepare("INSERT INTO cadastros(id,tipo,nome,contato,privacidade_versao,criado_em,atualizado_em) VALUES(?,'pessoa',?,?,'crm-interno-2026-11',?,?)").bind(id,name,contacts[0]?.valor||'',now,now);}
function crmGuardedInsert(env,table,columns,values,guard,args=[]){return env.DB.prepare('INSERT INTO '+table+'('+columns.join(',')+') SELECT '+columns.map(()=>'?').join(',')+' WHERE '+guard).bind(...values,...args);}
async function crmSavePerson(req,env,b){const id=crmID(b.id,'a pessoa')||crypto.randomUUID(),old=await crmRow(env,'crm_pessoas',b.id? id:null,'Pessoa'),nome=crmText(b.nome,120,'o nome',2),ativo=crmBool(b.ativo,'a situação da pessoa'),contacts=crmContacts(b.contatos||[]),now=new Date().toISOString();crmAssert(!(old&&b.criar_cadastro),'Crie o vínculo de uma pessoa existente pela ficha de apoio.');const statements=[crmUpsert(env,'crm_pessoas',id,{nome,ativo},now),env.DB.prepare('DELETE FROM crm_pessoa_contatos WHERE pessoa_id=?').bind(id),...contacts.map(c=>env.DB.prepare('INSERT INTO crm_pessoa_contatos(pessoa_id,tipo,valor) VALUES(?,?,?)').bind(id,c.tipo,c.valor))];let cadastroID=null;if(b.criar_cadastro===true){cadastroID=crypto.randomUUID();statements.push(crmNewSource(env,cadastroID,nome,contacts,now),env.DB.prepare('INSERT INTO crm_cadastro_pessoas(cadastro_id,pessoa_id,criado_em,atualizado_em) VALUES(?,?,?,?)').bind(cadastroID,id,now,now));}await env.DB.batch([...statements,crmAudit(env,req,'crm_salvar_pessoa',id,now)]);return json({ok:true,id,cadastro_id:cadastroID,atualizado_em:now});}
async function crmSaveLink(req,env,b){
 const sourceID=crmID(b.cadastro_id,'o cadastro de origem',true),personID=crmID(b.pessoa_id,'a identidade da pessoa',true);const source=await crmRow(env,'cadastros',sourceID,'Cadastro',true);crmAssert(['pessoa','acolhimento','contato'].includes(source.tipo),'Este tipo de cadastro não é uma pessoa ou solicitação de apoio.');await crmRow(env,'crm_pessoas',personID,'Pessoa',true);
 const old=await env.DB.prepare('SELECT pessoa_id,atualizado_em FROM crm_cadastro_pessoas WHERE cadastro_id=?').bind(sourceID).first();crmAssert(!old||old.pessoa_id===personID||b.confirmar_revisao===true,'Esse cadastro está vinculado a outra pessoa. Revise e confirme a correção do vínculo.',409);
 const now=new Date().toISOString(),auditID=crypto.randomUUID(),text=old&&old.pessoa_id!==personID?'Identidade do cadastro corrigida após conferência explícita.':'Identidade do cadastro conciliada após conferência da administração.';
 // First links use the unique source key; a competing insert rolls back the complete batch.
 // Existing links compare the identity that was reviewed. Only a successful mutation creates its audit marker.
 const statement=old?env.DB.prepare('UPDATE crm_cadastro_pessoas SET pessoa_id=?,atualizado_em=? WHERE cadastro_id=? AND pessoa_id=? AND atualizado_em=?').bind(personID,now,sourceID,old.pessoa_id,old.atualizado_em):env.DB.prepare('INSERT INTO crm_cadastro_pessoas(cadastro_id,pessoa_id,criado_em,atualizado_em) VALUES(?,?,?,?)').bind(sourceID,personID,now,now);
 const result=await env.DB.batch([statement,env.DB.prepare('INSERT INTO auditoria(id,ator,acao,registro_id,criado_em) SELECT ?,?,?,?,? WHERE changes()=1').bind(auditID,req.headers.get('oai-authenticated-user-id'),'crm_conciliar_identidade',sourceID,now),env.DB.prepare('INSERT INTO crm_movimentos(id,apoio_id,tipo,texto,ator,criado_em) SELECT lower(hex(randomblob(16))),id,?,?,?,? FROM op_apoios WHERE cadastro_id=? AND EXISTS(SELECT 1 FROM auditoria WHERE id=?)').bind('crm_conciliar_identidade',text,req.headers.get('oai-authenticated-user-id'),now,sourceID,auditID)]);
 crmAssert(result[0]?.meta?.changes===1,'O vínculo deste cadastro foi alterado. Atualize a consulta e confira a identidade antes de salvar novamente.',409);return json({ok:true,id:sourceID,pessoa_id:personID});
}
async function crmSaveFamily(req,env,b){const id=crmID(b.id,'a família')||crypto.randomUUID();if(b.id)await crmRow(env,'op_familias',id,'Família',true);const values={nome_referencia:crmText(b.nome_referencia,120,'a referência da família',2),contato:crmText(b.contato,150,'o contato'),notas:crmText(b.notas,600,'as observações')};crmAssert(Array.isArray(b.membros)&&b.membros.length<=100,'Confira os membros da família.');const members=b.membros.map(m=>({pessoa_id:crmID(m.pessoa_id,'o membro',true),papel:crmEnum(m.papel,['referencia','membro','cuidador'],'o papel na família')}));crmAssert(new Set(members.map(m=>m.pessoa_id)).size===members.length,'Uma pessoa aparece mais de uma vez na mesma família.');for(const m of members)await crmRow(env,'crm_pessoas',m.pessoa_id,'Pessoa',true);const now=new Date().toISOString();return crmWrite(env,req,id,[crmUpsert(env,'op_familias',id,values,now),env.DB.prepare('DELETE FROM crm_familia_membros WHERE familia_id=?').bind(id),...members.map(m=>env.DB.prepare('INSERT INTO crm_familia_membros(familia_id,pessoa_id,papel) VALUES(?,?,?)').bind(id,m.pessoa_id,m.papel))],'crm_salvar_familia',null,null,now);}
async function crmSaveService(req,env,b){const id=crmID(b.id,'o tipo de apoio')||crypto.randomUUID(),old=b.id?await crmRow(env,'crm_servicos',id,'Tipo de apoio',true):null;const values={nome:crmText(b.nome,120,'o nome do apoio',2),tipo:crmEnum(b.tipo,['cesta','atendimento','outro'],'a categoria'),ativo:crmBool(b.ativo,'a situação do apoio')};values.unidade_medida=crmEnum(b.unidade_medida||old?.unidade_medida||(values.tipo==='cesta'?'cesta':values.tipo==='atendimento'?'atendimento':'atividade'),['cesta','peca','item','atendimento','atividade'],'a unidade de medida');crmAssert((values.tipo==='cesta'&&values.unidade_medida==='cesta')||(values.tipo==='atendimento'&&values.unidade_medida==='atendimento')||(values.tipo==='outro'&&['peca','item','atividade'].includes(values.unidade_medida)),'A unidade de medida não corresponde à categoria do apoio.');if(old&&(old.tipo!==values.tipo||old.unidade_medida!==values.unidade_medida))crmAssert(!(await env.DB.prepare('SELECT 1 AS used FROM crm_realizacoes WHERE servico_id=? LIMIT 1').bind(id).first()),'A categoria já possui realizações e não pode ser trocada. Crie outro tipo para preservar o histórico.',409);const duplicate=await env.DB.prepare('SELECT id FROM crm_servicos WHERE nome=? COLLATE NOCASE AND id<>?').bind(values.nome,id).first();crmAssert(!duplicate,'Já existe um tipo de apoio com esse nome.',409);const now=new Date().toISOString();return crmWrite(env,req,id,[crmUpsert(env,'crm_servicos',id,values,now)],'crm_salvar_tipo_apoio',null,null,now);}
